export function getRegionalTopicIdeas(region='India', domain='Education & Learning', limit=1000) {
  const key = region === 'USA' ? 'USA' : 'India';
  const list = REGIONAL_TOPIC_BANK[key]?.[domain] || [];
  const count = Math.max(0, Math.min(Number(limit) || 0, list.length));
  return list.slice(0, count);
}

export function getRegionalDomainNames(region='India') {
  const key = region === 'USA' ? 'USA' : 'India';
  return Object.keys(REGIONAL_TOPIC_BANK[key] || {});
}

/* Topic detail helper: practical planning prompts, not verified factual claims. */
const REGION_CONTEXT = {
  India: [
    "भारतीय स्थानीय/क्षेत्रीय संदर्भ और भाषा विविधता जोड़ें",
    "शहर, कस्बे और ग्रामीण दर्शकों के अलग-अलग अनुभव दिखाएँ",
    "भारतीय उदाहरण दें; आँकड़े/कानून/तारीखें प्रकाशित करने से पहले सत्यापित करें",
    "दर्शक के रोज़मर्रा जीवन से जुड़ा व्यावहारिक उपयोग बताएँ",
    "समावेशी, सम्मानजनक और तथ्य-जाँच योग्य निष्कर्ष दें"
  ],
  USA: [
    "U.S. local/community context और audience diversity जोड़ें",
    "State/city differences को स्पष्ट रखें; पूरे देश पर एक जैसा दावा न करें",
    "U.S. उदाहरण दें; आँकड़े/कानून/तारीखें प्रकाशित करने से पहले सत्यापित करें",
    "दर्शक के रोज़मर्रा जीवन से जुड़ा व्यावहारिक उपयोग बताएँ",
    "समावेशी, सम्मानजनक और तथ्य-जाँच योग्य निष्कर्ष दें"
  ]
};

export function getRegionalTopicDetail(region='India', domain='Education & Learning', topic='') {
  const key = region === 'USA' ? 'USA' : 'India';
  const safeTopic = String(topic || '').trim();
  if (!safeTopic) return null;
  const points = REGION_CONTEXT[key].map((point, index) => `${index + 1}. ${point}`);
  return {
    region: key,
    domain,
    topic: safeTopic,
    suggestedHook: `इस विषय पर एक ऐसा सवाल उठाएँ जो ${key === 'India' ? 'भारतीय' : 'अमेरिकी'} दर्शक के अनुभव से जुड़ता हो।`,
    contentAngle: `“${safeTopic}” को सरल व्याख्या, वास्तविक जीवन के उदाहरण और उपयोगी निष्कर्ष के रूप में प्रस्तुत करें।`,
    keyPoints: points,
    factCheckNote: "किसी भी आँकड़े, सरकारी नीति, कानूनी जानकारी, स्वास्थ्य/वित्तीय सलाह, संस्था या वर्तमान घटना को प्रकाशित करने से पहले विश्वसनीय प्राथमिक स्रोत से जाँचें।",
    suggestedFormats: ["Short Reel / Short", "Carousel / Infographic", "Detailed Explainer", "Podcast Discussion", "Quiz / Q&A"],
    customDetailPrompt: "यहाँ अपनी अतिरिक्त जानकारी, तथ्य, उदाहरण, नाम, स्थान, तारीख, कहानी, मुख्य संदेश और CTA लिखें।"
  };
}

export function getRegionalTopicCatalog(region='India') {
  const key = region === 'USA' ? 'USA' : 'India';
  return Object.entries(REGIONAL_TOPIC_BANK[key] || {}).map(([domain, topics]) => ({
    domain,
    count: topics.length,
    topics: topics.map(topic => ({
      title: topic,
      detail: getRegionalTopicDetail(key, domain, topic)
    }))
  }));
}

